def total_with_tax(items, tax_rate=TAX_RATE):
    """Calculate total including tax, respecting tax_exempt flag.

    Items that have ``tax_exempt`` set to ``True`` are not subject to tax.
    All other items are taxed at the provided ``tax_rate`` (default ``TAX_RATE``).
    The result is rounded to two decimal places.
    """
    # Separate taxable and exempt items
    taxable_subtotal = sum(
        line_total(item["qty"], item["unit_price"]) for item in items if not item.get("tax_exempt")
    )
    exempt_subtotal = sum(
        line_total(item["qty"], item["unit_price"]) for item in items if item.get("tax_exempt")
    )
    total = exempt_subtotal + taxable_subtotal * (1 + tax_rate)
    return round(total, 2)
