from collections import defaultdict
from decimal import Decimal


def load_rows(path):
    """Read invoice rows from a CSV file."""
    with open(path, newline="") as f:
        return list(csv.DictReader(f))


def totals_by_customer(rows):
    """Total billed amount per customer using Decimal for monetary values."""
    totals = defaultdict(Decimal)
    for row in rows:
        # Convert amount string to Decimal for precise arithmetic
        totals[row["customer"]] += Decimal(row["amount"])
    # Return a regular dict with Decimal values
    return dict(totals)
"}

